style.css:
@-moz-document domain("pepper.pl") {
/* ============================================================
     Pepper runs the "Magritte" design-token frontend: nearly every
     surface, text and border color resolves from CSS custom
     properties on :root (e.g. --bgBaseSecondary, --textNeutralPrimary)
     and from utility classes that read those same tokens
     (color--bg-*, color--text-*). Re-pointing the tokens flips the
     bulk of the UI to dark. The remaining literal-color utilities
     (bg--main/em/off, text--color-charcoal/grey, …) and a few
     hardcoded surfaces are handled structurally afterwards.
     The site also ships a partial native dark under
     prefers-color-scheme; we set every surface explicitly so the
     theme is complete and identical regardless of the OS setting.
     ============================================================ */

  :root {
    color-scheme: dark !important;

    /* ---- Base surfaces (page / sections / cards) ---- */
    --bgBasePrimary: #14181d !important;
    --bgBaseSecondary: #1c2128 !important;
    --bgBaseTertiary: #21262d !important;
    --bgNeutralPrimary: #1c2128 !important;
    --bgNeutralSecondary: #21262d !important;
    --bgNeutralTertiary: #21262d !important;
    --bgNeutralQuaternary: #2d333b !important;

    /* ---- Inverted base (used as "dark on light" chips/badges) ---- */
    --bgAccentBrandAltPrimary: #2d333b !important;
    --bgAccentBrandAltSecondary: #21262d !important;
    --bgAccentBrandAltTertiary: #1c2128 !important;
    --bgAccentBrandAltQuaternary: #14181d !important;
    --bgAccentBrandAltMuted: #1c2128 !important;

    /* ---- Text scale (dark -> light) ---- */
    --textNeutralPrimary: #e6edf3 !important;
    --textNeutralSecondary: #9aa6b0 !important;
    --textNeutralTertiary: #909aa4 !important;
    --textNeutralQuaternary: #8b949e !important;
    --textTranslucentPrimary: #e6edf3 !important;
    --textTranslucentSecondary: #9aa6b0 !important;
    --textTranslucentTertiary: #909aa4 !important;
    --textTranslucentQuaternary: #8b949e !important;
    --textAccentBrandAlt: #9aa6b0 !important;

    /* ---- Icons / graphics scale ---- */
    /* Graphic/icon scale — kept legible (>=4.5 on #21262d) because some of
       these tokens render as text adornments (e.g. the "zł" input suffix). */
    --graphicNeutralPrimary: #e6edf3 !important;
    --graphicNeutralSecondary: #9aa6b0 !important;
    --graphicNeutralTertiary: #909aa4 !important;
    --graphicNeutralQuaternary: #8b949e !important;
    --graphicTranslucentPrimary: #e6edf3 !important;
    --graphicTranslucentSecondary: #9aa6b0 !important;
    --graphicTranslucentTertiary: #909aa4 !important;
    --graphicTranslucentQuaternary: #8b949e !important;

    /* ---- Borders (light hairlines -> dark) ---- */
    --borderNeutralPrimary: #2d333b !important;
    --borderNeutralSecondary: #2d333b !important;
    --borderNeutralTertiary: #3a424c !important;
    --borderNeutralQuaternary: #3a424c !important;
    --borderAccentBrandAlt: #2d333b !important;
    /* White-alpha "translucent" surface tokens (rgba(255,255,255,.05/.08/.12))
       paint a LIGHTER film over the dark card — the source of the "darker/lighter
       band" on vote boxes and outlined chips. Remap to SOLID elevated shades so a
       card reads as one uniform surface (a faint raised chip, never a film). */
    --bgTranslucentPrimary: #21262d !important;
    --bgTranslucentSecondary: #21262d !important;
    --bgTranslucentTertiary: #262c34 !important;
    --bgTranslucentQuaternary: #2d333b !important;

    /* ---- Link accent (raw #005498 navy -> readable dark-mode blue) ---- */
    --textAccentLink: #5fb0e6 !important;
    --bgAccentLink: #1f6feb !important;
    --bgAccentLinkMuted: #15233a !important;
    --borderAccentLink: #1f6feb !important;
    --graphicAccentLink: #5fb0e6 !important;

    /* ---- Pepper brand orange: keep the identity, settle it on dark ----
       The raw #f7641b / #ff7900 is a touch hot on near-black; nudge it
       to a warm orange that stays unmistakably Pepper but harmonizes
       with the cool dark palette. Text on it stays dark for contrast. */
    --bgAccentBrandPrimary: #f7641b !important;
    --bgAccentBrandSecondary: #e85a18 !important;
    --bgAccentBrandTertiary: #d4521a !important;
    --bgAccentBrandQuaternary: #c14a17 !important;
    --bgAccentBrandMuted: #2a1a12 !important;
    --textAccentBrand: #ff8a4d !important;
    --textAccentPrice: #ff8a4d !important;
    --borderAccentBrand: #f7641b !important;
    --borderAccentPrice: #f7641b !important;
    --graphicAccentBrand: #ff8a4d !important;

    /* ---- Premium (purple) accent ---- */
    --bgAccentPremiumMuted: #221836 !important;
    --textAccentPremium: #b690f8 !important;
    --borderAccentPremium: #813ef6 !important;

    /* ---- Status colors: keep semantic hue, settle onto dark ---- */
    --textStatusPositive: #3fb950 !important;
    --textStatusNegative: #f0857d !important;
    --textStatusWarning: #d6a425 !important;
    --textStatusInfo: #5fb0e6 !important;
    --bgStatusPositive: #238012 !important;
    --bgStatusNegative: #c2402b !important;
    --bgStatusWarning: #9f5c0c !important;
    --bgStatusInfo: #1f6feb !important;
    --bgStatusPositiveMuted: #102a18 !important;
    --bgStatusNegativeMuted: #3a1b16 !important;
    --bgStatusWarningMuted: #322a12 !important;
    --bgStatusInfoMuted: #15233a !important;
    --borderStatusPositive: #238012 !important;
    --borderStatusNegative: #c2402b !important;
    --borderStatusWarning: #9f5c0c !important;
    --borderStatusInfo: #1f6feb !important;

    /* ---- Deal temperature scale (cold blue -> hot red) ----
       Pepper's signature: a deal's "degrees" run blue(cold) ->
       orange -> red(hot). Keep those hues, just brighten for dark. */
    --temperature10: #5fb0e6 !important;
    --temperature30: #f3a21c !important;
    --temperature50: #f7641b !important;
    --temperature70: #f0857d !important;
    --temperature90: #f0857d !important;
    --temperature10Muted: #15233a !important;
    --temperature30Muted: #322a12 !important;
    --temperature50Muted: #2a1a12 !important;
    --temperature70Muted: #3a1b16 !important;
    --temperature90Muted: #3a1b16 !important;

    /* ---- Decorative pastels (used for tags / pills) ---- */
    --decorativeBlueMuted: #15233a !important;
    --decorativeGreenMuted: #102a18 !important;
    --decorativeRedMuted: #3a1b16 !important;
    --decorativeOrangeMuted: #2a1a12 !important;
    --decorativeYellowMuted: #322a12 !important;
    --decorativePurpleMuted: #221836 !important;
    --decorativeTurquoiseMuted: #0e2a30 !important;
  }

  /* ---- Base page ---- */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* ---- Soften every default light border into a dark hairline ---- */
  * { border-color: #2d333b !important; }

  /* ============================================================
     Literal-color background utilities (don't read a token)
     bg--main #fff, bg--em #f3f5f7, bg--off #e9eaec
     ============================================================ */
  .bg--main { background-color: #1c2128 !important; }
  .bg--em   { background-color: #21262d !important; }
  .bg--off  { background-color: #14181d !important; }

  /* ============================================================
     Literal-color text utilities
     charcoal #35373b (dark!), grey #bfc3c8, greyShade #8f949b
     ============================================================ */
  .text--color-charcoal { color: #e6edf3 !important; }
  .text--color-grey,
  .text--color-greyShade { color: #9aa6b0 !important; }
  .text--color-brandPrimary { color: #ff8a4d !important; }
  .text--color-yellow { color: #d6a425 !important; }

  /* ============================================================
     Header / global nav (white bar -> deep neutral dark)
     ============================================================ */
  header,
  header[class*="header"],
  .navTopBar, .nav-bar, #page-header {
    background-color: #0d1117 !important;
  }
  header .color--bg-BaseSecondary,
  header [class*="bg--"],
  header > div {
    background-color: #0d1117 !important;
  }
  /* Make the WHOLE bar read as one uniform #0d1117 surface. The nav wrappers
     beside the logo (.nav-search--navigation and the flex/lbox/aGrid layout
     divs) inherit --bgBaseSecondary (#1c2128), so a lighter block sat to the
     right of the (transparent) logo — a visible seam, not one continuous bar.
     Blank every header LAYOUT container (div/span/form/nav/ul/li/section) to
     transparent so the bar's #0d1117 shows through edge-to-edge. Real controls
     keep their own fill: the orange "Utwórz alert"/"Opublikuj" pills and the
     count badge are set by the brand-CTA/circle rules above, and the search
     input by the .input rule below — all !important and later in source, so
     they override this blanket. <button> is deliberately NOT blanked here so a
     ghost icon-button wrapper can't strip a CTA's fill. The [class] qualifier
     lifts specificity to (0,0,1,2) so this beats the deal-card rule
     `main [class*="box--"]` (0,0,1,1) — the header nests inside <main> and its
     layout wrappers carry box--* classes, which is exactly what painted the
     #1c2128 seam beside the logo. */
  header div[class], header span[class], header form[class],
  header nav[class], header ul[class], header li[class],
  header section[class] {
    background-color: transparent !important;
  }
  header a, header button { color: #e6edf3 !important; }

  /* Header sprite icons (Menu, person, voucher, categories, comments,
     brightness, …) are monochrome <svg class="icon icon--X"><use …></svg>
     refs whose fill resolves to BLACK — invisible on the dark header. They're
     all chrome, so light them uniformly. */
  header svg.icon, header svg.icon use,
  header svg[class*="icon"], header svg[class*="icon"] use {
    fill: #e6edf3 !important;
    color: #e6edf3 !important;
  }

  /* Brand logo: the home link (.nav-logo) hides its "Pepper.pl" text off-screen
     and paints a background-image SVG (logo/default-dark_*.svg). That SVG bakes a
     near-black navy (#001729) wordmark next to the orange (#fb4c01) flame, so the
     wordmark is invisible on our dark header. A `fill:` rule can't touch a
     background-image, so swap in the SAME artwork recolored to a light wordmark
     (flame orange preserved) as an inline data-URI. */
  header a.nav-logo, header a[data-t="homeLink"],
  header a[rel="home"][href="/"] {
    background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22101%22%20height%3D%2255%22%20fill%3D%22none%22%20viewBox%3D%220%200%20101%2055%22%3E%3Cg%20clip-path%3D%22url%28%23clip0_2029_107%29%22%20style%3D%22transform%3A%20translateY%285px%29%22%3E%3Cpath%20fill%3D%22%23fb4c01%22%20d%3D%22M12.213%2034.583c-.538.013-.527-.481-.203-.61.364-.147.924-.378%201.291-.61%203.715-2.336%201.198-7.29-1.87-6.825-.986.15-1.36.239-1.872.015-1.32-.578-1.578-2.03-1.007-3.112.164-.656-.334-.554-.591-.313q-.064.04-.124.082c-1.54%201.143-2.939%203.221-2.722%205.933.25%203.129%202.556%204.56%203.322%204.826.344.12.335.654-.083.614-1.78-.17-3.866-1.102-5.507-2.832C.52%2029.297-.566%2025.533.594%2021.917c1.738-5.415%208.627-7.489%208.024-11.436-.226-1.1.75-1.162%201.167-.941%201.45.866%202.014%201.885%202.335%202.907%201.05%203.334-.522%204.317%201.05%206.084.358.359.954.75%201.542.82%201.403.162%202.045-.928%202.117-1.463s.54-.56.746-.356c5.013%205.568%201.864%2012.09-.098%2014.209-2.114%202.284-4.797%202.83-5.264%202.842%22%2F%3E%3Cpath%20fill%3D%22%23e6edf3%22%20fill-rule%3D%22evenodd%22%20d%3D%22M31.576%2017.453q1.943%200%203.348.63%201.405.632%202.17%201.81.766%201.177.766%202.79%200%201.632-.766%202.8-.765%201.17-2.17%201.81t-3.348.64H28.68v3.62c0%20.935-.758%201.693-1.694%201.693H25.86a.55.55%200%200%201-.549-.548V19.939a2.486%202.486%200%200%201%202.486-2.486zm-.187%207.751q1.53%200%202.315-.66.785-.662.785-1.861.001-1.199-.785-1.85-.785-.652-2.315-.652h-1.434c-.703%200-1.274.57-1.274%201.274v3.75z%22%20clip-rule%3D%22evenodd%22%2F%3E%3Cpath%20fill%3D%22%23e6edf3%22%20d%3D%22M95.614%2023.589q.456-.625%201.157-1.017c.55-.305%201.565-.496%202.292-.572a.68.68%200%200%201%20.752.679v1.502a.697.697%200%200%201-.7.696h-.003c-.91%200-2.01.255-2.547.765q-.806.765-.806%202.356V31.7a1.55%201.55%200%200%201-1.55%201.55h-1.165a.51.51%200%200%201-.51-.51V22.61c0-.267.216-.483.483-.483h2.114c.266%200%20.483.216.483.482z%22%2F%3E%3Cpath%20fill%3D%22%23e6edf3%22%20fill-rule%3D%22evenodd%22%20d%3D%22M55.384%2032.084q.384.421.868.709%201.055.62%202.46.62%201.57%200%202.832-.713a5.16%205.16%200%200%200%201.984-1.995q.724-1.282.724-3.018%200-1.737-.724-3.018a5.16%205.16%200%200%200-1.984-1.995q-1.26-.713-2.832-.713-1.467%200-2.512.61-.547.32-.96.827v-.723a.55.55%200%200%200-.55-.549h-1.982a.55.55%200%200%200-.549.549v15.358a.55.55%200%200%200%20.549.549h.773a1.903%201.903%200%200%200%201.903-1.903zm.585-6.05a2.63%202.63%200%200%201%201.023-1.065%202.9%202.9%200%200%201%201.447-.362q.786%200%201.427.362.64.361%201.023%201.064t.382%201.654q0%20.971-.382%201.654a2.66%202.66%200%200%201-1.023%201.043q-.64.362-1.427.362-.806%200-1.447-.361a2.67%202.67%200%200%201-1.023-1.044q-.382-.683-.382-1.654%200-.951.382-1.654m14.176%206.76a3.7%203.7%200%200%201-.868-.71v4.596a1.903%201.903%200%200%201-1.903%201.903h-.773a.55.55%200%200%201-.549-.549V22.675a.55.55%200%200%201%20.55-.549h1.982a.55.55%200%200%201%20.549.549v.723q.413-.506.96-.827%201.045-.61%202.512-.61%201.572%200%202.832.713a5.16%205.16%200%200%201%201.985%201.995q.723%201.281.723%203.018%200%201.735-.723%203.018a5.16%205.16%200%200%201-1.985%201.995q-1.26.713-2.832.713-1.406%200-2.46-.62m.74-7.824a2.63%202.63%200%200%200-1.023%201.064q-.382.703-.382%201.654%200%20.971.382%201.654.384.681%201.024%201.043.641.362%201.447.362.786%200%201.426-.361.64-.363%201.023-1.044.383-.683.383-1.654%200-.951-.383-1.654a2.63%202.63%200%200%200-1.023-1.064%202.85%202.85%200%200%200-1.426-.362q-.807%200-1.447.362m-23.245-2.305q-1.313-.703-2.945-.703-1.695%200-3.05.734a5.3%205.3%200%200%200-2.108%202.036q-.754%201.302-.754%202.956t.785%202.945%202.212%202.037%203.328.744q1.51%200%202.666-.465a5.2%205.2%200%200%200%201.486-.898.596.596%200%200%200%20.05-.855l-.465-.505a1.4%201.4%200%200%200-1.55-.349l-.544.22q-.672.267-1.54.268-1.013%200-1.736-.362a2.72%202.72%200%200%201-1.465-1.87h7.971c.25%200%20.458-.192.48-.44v-.005q.021-.238.021-.424%200-1.798-.764-3.08a5.3%205.3%200%200%200-2.078-1.984m-4.382%202.098q.63-.362%201.457-.362t1.447.362.972%201.002q.233.426.3.951H41.97q.08-.52.307-.94.35-.651.982-1.013M85.07%2021.96q1.632%200%202.946.704a5.3%205.3%200%200%201%202.077%201.984q.765%201.282.765%203.08%200%20.186-.021.424v.005a.48.48%200%200%201-.48.44h-7.972q.101.45.328.826.414.682%201.137%201.044t1.737.362q.868%200%201.54-.269l.544-.219a1.4%201.4%200%200%201%201.549.35l.466.504a.596.596%200%200%201-.05.855q-.638.556-1.486.898-1.158.465-2.667.465-1.902%200-3.328-.744-1.426-.745-2.212-2.037-.785-1.291-.785-2.945t.754-2.956a5.3%205.3%200%200%201%202.109-2.036q1.353-.734%203.049-.734m.02%202.44q-.827%200-1.457.362t-.982%201.013q-.227.42-.306.94h5.465a2.7%202.7%200%200%200-.301-.95%202.57%202.57%200%200%200-.972-1.003q-.62-.362-1.447-.362%22%20clip-rule%3D%22evenodd%22%2F%3E%3C%2Fg%3E%3Cdefs%3E%3CclipPath%20id%3D%22clip0_2029_107%22%3E%3Cpath%20fill%3D%22%23fff%22%20d%3D%22M0%200h100v29.31H0z%22%20transform%3D%22translate%280%209.34375%29%22%2F%3E%3C%2FclipPath%3E%3C%2Fdefs%3E%3C%2Fsvg%3E") !important;
  }

  /* The sticky header ships with a scroll-driven opacity transition and a
     `mute--opacity-0` state, so mid-scroll it renders semi-transparent and
     page content ghosts through. Force it fully opaque + solid dark and kill
     the fade so nothing ever bleeds through the bar. */
  header, header.header--transition,
  header[class*="header--"], header[class*="opacity"] {
    opacity: 1 !important;
    transition: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
  }

  /* "Opublikuj" / primary brand CTA pills keep the orange.
     Specificity bumped (.button.button--type-primary) so our dark text
     wins over the site's own inverted-white label utility on the pill. */
  .btn--mode-primary,
  .button--type-primary,
  .button.button--type-primary,
  [class*="button--type-primary"],
  a[href*="/publish"], a[href*="poll/new"] {
    background-color: #f7641b !important;
    color: #1a1205 !important;
    border-color: #f7641b !important;
  }
  .btn--mode-primary *,
  .button--type-primary *,
  .button.button--type-primary *,
  [class*="button--type-primary"] * { color: #1a1205 !important; }

  /* ---- ...but `button--type-primary` is only ORANGE in `button--mode-brand`.
     The same type carries six other modes, each of which reads its own
     `--background-default` token (grey / expired / danger / success / info /
     warning). The blanket rule above painted every one of them brand orange:
     the footer's "Obserwuj nas" social discs (mode-grey) became seven orange
     blobs, the mobile bottom-bar "Alerty" tab became a raw orange square, and
     — worst — an EXPIRED deal's dead "Idź do okazji" CTA (mode-expired) looked
     exactly like a live one. Restore each mode from the tokens it should read.
     Two classes = specificity (0,0,2,0), so these beat the (0,0,1,0) rule
     above (and its `*` descendant rule) regardless of source order. */
  .button--type-primary.button--mode-grey {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .button--type-primary.button--mode-grey * { color: #e6edf3 !important; }
  .button--type-primary.button--mode-grey svg,
  .button--type-primary.button--mode-grey svg use { fill: #e6edf3 !important; }
  .button--type-primary.button--mode-expired {
    background-color: #21262d !important;
    color: #9aa6b0 !important;
    border-color: #2d333b !important;
  }
  .button--type-primary.button--mode-expired * { color: #9aa6b0 !important; }
  .button--type-primary.button--mode-danger {
    background-color: #c2402b !important;
    color: #fff2ef !important;
    border-color: #c2402b !important;
  }
  .button--type-primary.button--mode-danger * { color: #fff2ef !important; }
  .button--type-primary.button--mode-success {
    background-color: #238012 !important;
    color: #f2fff2 !important;
    border-color: #238012 !important;
  }
  .button--type-primary.button--mode-success * { color: #f2fff2 !important; }
  .button--type-primary.button--mode-info {
    background-color: #1f6feb !important;
    color: #f2f8ff !important;
    border-color: #1f6feb !important;
  }
  .button--type-primary.button--mode-info * { color: #f2f8ff !important; }
  .button--type-primary.button--mode-warning {
    background-color: #9f5c0c !important;
    color: #fff8ef !important;
    border-color: #9f5c0c !important;
  }
  .button--type-primary.button--mode-warning * { color: #fff8ef !important; }

  /* Outline / text buttons carry their meaning in the LABEL colour, which the
     blanket `.btn, .button { color }` rule below flattens to one neutral grey:
     the header's "Opublikuj" (secondary + mode-brand) and the filter panel's
     "Zresetuj" (text + mode-primary) both ship brand orange natively. The
     blanket `* { border-color }` reset likewise erases their orange outline.
     Restore label + outline per mode; two classes beat both blankets. */
  .button--type-secondary.button--mode-brand,
  .button--type-tertiary.button--mode-brand,
  .button--type-text.button--mode-brand,
  .button--type-text.button--mode-primary {
    color: #ff8a4d !important;
    border-color: #f7641b !important;
  }
  .button--type-secondary.button--mode-brand *,
  .button--type-tertiary.button--mode-brand *,
  .button--type-text.button--mode-brand *,
  .button--type-text.button--mode-primary * { color: #ff8a4d !important; }
  .button--type-secondary.button--mode-danger,
  .button--type-tertiary.button--mode-danger,
  .button--type-text.button--mode-danger {
    color: #f0857d !important;
    border-color: #c2402b !important;
  }
  .button--type-secondary.button--mode-danger *,
  .button--type-tertiary.button--mode-danger *,
  .button--type-text.button--mode-danger * { color: #f0857d !important; }
  .button--type-secondary.button--mode-success,
  .button--type-tertiary.button--mode-success,
  .button--type-text.button--mode-success {
    color: #3fb950 !important;
    border-color: #238012 !important;
  }
  .button--type-secondary.button--mode-success *,
  .button--type-tertiary.button--mode-success *,
  .button--type-text.button--mode-success * { color: #3fb950 !important; }
  .button--type-secondary.button--mode-info,
  .button--type-tertiary.button--mode-info,
  .button--type-text.button--mode-info {
    color: #5fb0e6 !important;
    border-color: #1f6feb !important;
  }
  .button--type-secondary.button--mode-info *,
  .button--type-tertiary.button--mode-info *,
  .button--type-text.button--mode-info * { color: #5fb0e6 !important; }
  .button--type-secondary.button--mode-warning,
  .button--type-tertiary.button--mode-warning,
  .button--type-text.button--mode-warning {
    color: #d6a425 !important;
    border-color: #9f5c0c !important;
  }
  .button--type-secondary.button--mode-warning *,
  .button--type-tertiary.button--mode-warning *,
  .button--type-text.button--mode-warning * { color: #d6a425 !important; }

  /* Brand-orange count/notification circle badge (native white text on the
     #f7641b fill only reaches ~3:1) -> dark text for a readable, on-brand chip */
  .circle--primary, .circle--primary * { color: #1a1205 !important; }

  /* Red notification/alert count badge on the header bell (span.circle--alert).
     The header layout blanket `header span[class] { background: transparent }`
     (0,0,1,2) stripped its native red fill, so the indicator vanished. Restore a
     vivid red dot; `header .circle--xxs.circle--alert` is (0,0,2,1) so it wins. */
  header .circle--xxs.circle--alert,
  .circle--alert {
    background-color: #da3633 !important;
    color: #ffffff !important;
  }

  /* Active/selected segmented-control tab (e.g. "Auto"/sort segments, and the
     "Powiązane dyskusje" tab on a deal page). Natively it's a pale-peach bg
     (rgb(252,230,217)) + orange text; the dark equivalent is a dark brand-muted
     bg with brand-orange TEXT, which keeps the selected affordance and stays
     well above 4.5:1. The background MUST be set on the button itself
     (button--mode-light leaves the peach fill in place otherwise — it leaked as
     a bright pill on the dark page). */
  .button--selected,
  .button--type-segmented.button--selected,
  .button--mode-light.button--selected,
  [class*="button--mode-light"].button--selected {
    background-color: #2a1a12 !important;
    border-color: #f7641b !important;
  }
  .button--selected,
  .button--selected *,
  .button.button--selected,
  .button.button--selected *,
  .button--type-segmented.button--selected,
  .button--type-segmented.button--selected * { color: #ff8a4d !important; }

  /* Feed sort tabs ("Popularne / Najgorętsze / Gorące / Wszystkie"): the bar
     itself is the elevated #1c2128 surface (.color--bg-BaseSecondary), but each
     tab LI (.subNavMenu-item--separator) carried a DARKER #0d1117 box, so every
     label read as a recessed chip on the bar. Unify the LIs to the bar's #1c2128
     so the tabs sit flush on one surface (the active one keeps its orange
     underline + brand-orange text). */
  .subNavMenu--light .subNavMenu-item--separator,
  li.subNavMenu-item--separator,
  .subNavMenu-item--separator {
    background-color: #1c2128 !important;
  }
  .color--bg-BaseSecondary.aGrid--sticky { background-color: #1c2128 !important; }

  /* ============================================================
     Search box (header + search page)
     ============================================================ */
  .input,
  input[type="text"], input[type="search"], input[type="email"],
  input[type="password"], input[type="number"], textarea, select {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  ::placeholder { color: #8b949e !important; opacity: 1 !important; }
  /* Some inputs paint the placeholder via the translucent-primary token;
     force a legible muted grey there too. */
  .input::placeholder,
  input::placeholder, textarea::placeholder { color: #8b949e !important; }
  .input-with-icon svg, .input-icon { color: #9aa6b0 !important; }

  /* Search autocomplete / suggestion dropdown.
     Only `.popover-content` is a real panel — `[class*="popover"]` also matched
     the full-viewport `.popover-cover` scrim, the `.popover--layout-fixed`
     wrapper, `.popover-portal` and `.popover-origin`, all natively transparent
     (see the popover block near the end). `[class*="dropdown"]` is qualified to
     block elements so it can't paint a box behind the 10x7 `svg` caret. */
  .autocomplete, .typeahead, [class*="popover-content"], [role="listbox"],
  div[class*="dropdown"], ul[class*="dropdown"], [class*="menu--"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ============================================================
     Category / filter chips (HP, Laptopy, …) and tag pills
     ============================================================ */
  .chip, .tag, .label,
  [class*="chip"], [class*="tag--"], [class*="pill"],
  .cept-pill, .navLink--pill,
  .chip--variant-outlined, [class*="chip--variant-outlined"] {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .chip:hover, [class*="chip"]:hover { background-color: #2d333b !important; }
  /* The blanket chip rule above is a substring match, so it also swallowed
     every SEMANTIC chip variant: `.chip--type-expired` (natively an inverted
     light chip), danger, warning and info all collapsed to the same neutral
     grey — an expired deal's "Wygasła 2 tyg. temu" chip became visually
     identical to a live deal's "Dodano 3 godz. temu" chip. Restore each state
     (dark-mode equivalents of the tokens the site reads); one extra class of
     specificity is unnecessary since these are later in source. */
  .chip--type-expired {
    background-color: #3a424c !important;
    color: #e6edf3 !important;
    border-color: #3a424c !important;
  }
  .chip--type-danger {
    background-color: #c2402b !important;
    color: #fff2ef !important;
    border-color: #c2402b !important;
  }
  .chip--type-warning {
    background-color: #3a1b16 !important;
    color: #f0857d !important;
    border-color: #5a2a22 !important;
  }
  .chip--type-info {
    background-color: #15233a !important;
    color: #5fb0e6 !important;
    border-color: #1f3a5a !important;
  }
  /* A chip's inner spans must not paint their own surface: the "Wygasa za
     22g 41m" countdown wraps its timer in a `box--all-i` span, which the
     deal-detail rule `main [class*="box--"]` (0,0,1,1) filled with the card
     shade — a darker block sitting inside the chip. Two classes = (0,0,2,0),
     so these win and the chip reads as one pill in its own state colour. */
  .chip.chip--type-default *, .chip.chip--type-expired *,
  .chip.chip--type-danger *, .chip.chip--type-warning *,
  .chip.chip--type-info * { background-color: transparent !important; }
  .chip.chip--type-default * { color: #c4cdd6 !important; }
  .chip.chip--type-expired * { color: #e6edf3 !important; }
  .chip.chip--type-danger * { color: #fff2ef !important; }
  .chip.chip--type-warning * { color: #f0857d !important; }
  .chip.chip--type-info * { color: #5fb0e6 !important; }
  /* Selected chip/filter pill -> brand-orange fill with dark text. Scoped to
     chip/pill/tag/tab controls; nav-menu "selected" links are handled below as
     coloured text, NOT an orange fill (avoids blue-link-on-orange). */
  .chip--selected, .chip--active, [aria-selected="true"],
  [class*="chip--selected"], [class*="pill--selected"],
  [class*="tag--selected"], [class*="tab--selected"] {
    background-color: #f7641b !important;
    color: #1a1205 !important;
    border-color: #f7641b !important;
  }
  .chip--selected *, .chip--active *, [aria-selected="true"] *,
  [class*="chip--selected"] *, [class*="pill--selected"] *,
  [class*="tag--selected"] *, [class*="tab--selected"] * {
    color: #1a1205 !important;
  }
  /* Selected nav / sub-nav menu links: brand-orange TEXT (no fill), readable
     on the dark surface. */
  .navMenu-link--selected, .navMenu-link--selected *,
  .subNavMenu-link--selected, .subNavMenu-link--selected *,
  a.router-link-active[class*="--selected"],
  a.router-link-active[class*="--selected"] * {
    background-color: transparent !important;
    color: #ff8a4d !important;
  }

  /* ============================================================
     Deal / thread cards
     ============================================================ */
  .thread, .cept-thread-item,
  article, [class*="threadGrid"], [class*="thread--"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  .thread--shadow, .thread--newCard { box-shadow: none !important; }
  /* Image holder inside a card: keep it the SAME shade as the card body
     (#1c2128) so a deal card reads as ONE uniform surface — a different
     elevated shade here showed as a lighter block beside the card text. */
  .imgFrame, .thread-image, [class*="imgFrame"], .cept-thread-image,
  picture, .imgFrame-container, [class*="imgFrame-container"],
  .threadListCard-image {
    background-color: #1c2128 !important;
  }
  /* The image frame (.imgFrame--darken-new) paints a near-transparent
     darkening FILM over the product photo via an absolutely-positioned
     ::after that reads a --bgTranslucent* token (natively rgba(.,.,.,.05)).
     Our --bgTranslucent* remap makes those tokens SOLID, which turned that
     5%-alpha film into a fully OPAQUE box that completely covered the photo
     (deal thumbnails rendered as flat dark squares). The film is purely
     decorative, so neutralize the frame's own overlay pseudo-elements — the
     photo shows again and the card stays dark. */
  .imgFrame::before, .imgFrame::after,
  [class*="imgFrame"]::before, [class*="imgFrame"]::after {
    background-color: transparent !important;
    background-image: none !important;
  }
  /* Card title + body */
  .thread-title, .thread-title a, .cept-tt {
    color: #e6edf3 !important;
  }
  .thread-title a:hover { color: #ffffff !important; }
  /* Deal price (orange) + struck-through old price.
     `span.threadItemCard-price` raises specificity to (0,0,1,1): the deal-detail
     card rule `[class*="threadItemCard"]` (0,0,1,0, later in source) was a
     substring match on `threadItemCard-price` and greyed every price in the
     "Podobne okazje" strip — this beats it so prices stay orange. */
  .thread-price, .threadItemCard-price, span.threadItemCard-price,
  [class*="text-AccentPrice"] {
    color: #ff8a4d !important;
  }
  .mute--text, .text--strikethrough, del, s {
    color: #8b949e !important;
  }

  /* Coupon-code "voucher" ticket (the dashed pill holding a copyable code like
     "SLC26" beside "Pobierz kod"): its dashed BRAND-ORANGE border is the
     copy-the-code affordance. The `* { border-color: #2d333b }` reset flattened
     it to a plain grey box. `.voucher.border--dash` (0,0,2,0) restores the hue. */
  .voucher.border--dash, div.aGrid.voucher {
    border-color: #f7641b !important;
  }
  /* The "Pobierz kod i przejdź" voucher-teaser pill carries the same brand-border
     affordance via the `color--border-AccentBrand` utility (natively #f97936). The
     `* { border-color: #2d333b }` reset flattened it to grey on every teaser, so the
     coupon edge no longer read as brand. Restore the utility — it's only ever used on
     voucher elements here; (0,0,1,0) beats the `*` reset. */
  .color--border-AccentBrand { border-color: #f7641b !important; }

  /* Rating stars (App Store / merchant ratings) are SVG <use href="…#star">
     glyphs that paint from `color`/`fill`; a broad neutral rule greyed them so a
     "4,6 ★★★★★" read as neutral grey stars. Keep them gold. */
  svg.icon--star, svg.icon--star use,
  .icon--star, .icon--star use {
    color: #f3a21c !important;
    fill: #f3a21c !important;
  }

  /* Active carousel-pagination dot (the "••••" nav on merchant/coupon rails)
     is brand-orange natively; a neutral rule collapsed it to grey, erasing the
     current-slide indicator. `.dot.color--graphic-AccentBrand` (0,0,2,0) wins. */
  .dot.color--graphic-AccentBrand {
    background-color: #ff8a4d !important;
    color: #ff8a4d !important;
  }

  /* ============================================================
     Deal temperature badge (the "175°" heat counter)
     ============================================================ */
  .vote-box, .cept-vote-box, [class*="voteBox"], [class*="vote-temp"],
  .vote-box--change, [class*="vote-box--"] {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  /* Pepper's signature is the temperature SCALE: a deal's degrees run cold-blue
     -> warm-orange -> hot-red, and a brand-new deal shows a neutral "Nowe"
     label (--inert) instead of a number. A flat `.vote-temp { color }` rule
     used to paint all four states the same orange, so "Nowe", a 7° dud and a
     7401° smash hit were indistinguishable. Colour each state from the
     temperature tokens instead (the site's own modifier rules are not
     !important, so the flat rule beat them on source order). */
  .vote-temp, .cept-vote-temp { color: #c4cdd6 !important; }
  .vote-temp--inert { color: #e6edf3 !important; }
  .vote-temp--cold, .vote-temp--colder, .vote-temp--frozen,
  .vote-temp-chip--cold { color: #5fb0e6 !important; }
  .vote-temp--warm, .vote-temp-chip--warm { color: #f7641b !important; }
  .vote-temp--hot, .vote-temp--burn, .vote-temp-chip--hot { color: #f0857d !important; }
  .vote-box--muted .vote-temp { color: #9aa6b0 !important; }
  .vote-button, .cept-vote-button { color: #9aa6b0 !important; }
  /* The two vote arrows carry the hot/cold affordance: "colder" (down) is blue,
     "hotter" (up) is red — both coloured natively (the arrow glyph is an SVG
     <use> whose fill = currentColor). The flat `.vote-button {color}` above
     greyed both, so they read identically. Restore per mode; the icon selector
     is (0,0,2,0) so it also beats the button-level grey via the glyph. */
  .vote-button--mode-down, .vote-button--mode-down .vote-icon,
  .cept-vote-button--mode-down { color: #5fb0e6 !important; }
  .vote-button--mode-up, .vote-button--mode-up .vote-icon,
  .cept-vote-button--mode-up { color: #f0857d !important; }

  /* ============================================================
     Buttons (secondary / shaped)
     ============================================================ */
  .btn, .button {
    color: #e6edf3 !important;
  }
  .btn--mode-secondary,
  .button--type-secondary,
  [class*="button--type-secondary"] {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .btn--mode-secondary:hover,
  .button--type-secondary:hover { background-color: #2d333b !important; }

  /* "Idź do okazji" / go-to-deal CTA keeps the brand orange.
     A former `a[rel*="nofollow"][class*="button"]` fallback lived here and was
     far too broad: EVERY nofollow anchor carrying "button" in its class got the
     orange fill, which turned the header's ghost "Utwórz alert" pill orange, the
     mobile bottom-bar "Alerty" tab into a raw orange square, and an expired
     deal's dead CTA into a live-looking one. The real CTA already resolves via
     `.button--type-primary.button--mode-brand`, so the fallback only did harm. */
  .cept-dealBtn, [class*="dealBtn"] {
    background-color: #f7641b !important;
    color: #1a1205 !important;
    border-color: #f7641b !important;
  }

  /* ============================================================
     Search page: filters sidebar + sort
     ============================================================ */
  .filterGroup, .sidebar, aside,
  [class*="filter"], [class*="sidebar"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .filterGroup .box--all, .filter-card, [class*="filterCard"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Sort dropdown + select boxes */
  .select, .selectBox, [class*="select--"] {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* The sidebar-widget sort dropdowns ("Popularne ▾" on the "Do obejrzenia" /
     "Dyskusje" rails) are a `.plainSelect` whose brand-orange affordance is the
     `color--text-AccentBrand` utility. Its visible label sits in a
     `.plainSelect-fake` child carrying `box--all-b`, and the wrapper itself
     carries `lbox--v-1` — both match the deal-detail blanket
     `main [class*="box--"]` (0,0,1,1, !important), which greyed the label + caret
     to neutral, so a branded sort control read as inert grey. Restore the accent
     on the control, its fake label and the caret glyph. */
  .plainSelect.color--text-AccentBrand,
  .plainSelect.color--text-AccentBrand .plainSelect-fake,
  .plainSelect.color--text-AccentBrand select {
    color: #ff8a4d !important;
  }
  .plainSelect.color--text-AccentBrand svg,
  .plainSelect.color--text-AccentBrand use {
    color: #ff8a4d !important;
    fill: #ff8a4d !important;
  }
  /* Checkbox + radio surfaces */
  input[type="checkbox"], input[type="radio"] {
    background-color: #21262d !important;
    border-color: #3a424c !important;
  }
  /* Selected filter radio (search sidebar): the checked `.radio-icon` shows an
     orange RING as its selected affordance. The `* { border-color: #2d333b }`
     reset greyed that ring so a selected option's outer edge read the same as an
     unselected one (only the inner dot still differed). Restore the orange ring on
     the checked radio; `.radio-input:checked + .radio-icon` (0,0,2,0) beats `*`. */
  .radio-input:checked + .radio-icon { border-color: #f7641b !important; }
  /* ---- Price range slider (Cena) ----
     Markup: a .rangeSlider-container holds two <input type=range>
     (.rangeSlider--from / --to) overlaid on .rangeSlider-line (the visual
     track) + .rangeSlider-line-active (the selected fill). The naive
     "[class*=rangeSlider]{background:orange}" painted the full-width INPUTs
     solid orange, so a thick orange bar protruded past the round thumbs.
     Fix: inputs transparent; track dark; fill orange; thumbs = round orange. */
  .rangeSlider-container { background-color: transparent !important; }
  input.rangeSlider, input[class*="rangeSlider--"] {
    background-color: transparent !important;
    -webkit-appearance: none !important;
    appearance: none !important;
  }
  .rangeSlider-line { background-color: #2d333b !important; }
  .rangeSlider-line-active { background-color: #f7641b !important; }
  /* Round draggable thumbs on the overlaid range inputs */
  input.rangeSlider::-webkit-slider-thumb,
  input[class*="rangeSlider--"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: 16px !important; height: 16px !important;
    border-radius: 50% !important;
    background-color: #f7641b !important;
    border: 2px solid #14181d !important;
    cursor: pointer !important;
  }
  input.rangeSlider::-moz-range-thumb,
  input[class*="rangeSlider--"]::-moz-range-thumb {
    width: 16px !important; height: 16px !important;
    border-radius: 50% !important;
    background-color: #f7641b !important;
    border: 2px solid #14181d !important;
    cursor: pointer !important;
  }
  /* Split by engine: one invalid selector drops the WHOLE list, so a mixed
     -webkit-/-moz- prelude styles the track in neither browser. */
  input.rangeSlider::-webkit-slider-runnable-track,
  input[class*="rangeSlider--"]::-webkit-slider-runnable-track {
    background-color: transparent !important;
  }
  input.rangeSlider::-moz-range-track,
  input[class*="rangeSlider--"]::-moz-range-track {
    background-color: transparent !important;
  }
  /* Any explicit handle element the widget renders */
  .rangeSlider-handle, [class*="rangeSlider-handle"] {
    background-color: #f7641b !important;
    border-radius: 50% !important;
  }

  /* ============================================================
     Deal detail page
     ============================================================ */
  .threadItemCard, .cept-thread-content,
  [class*="threadItemCard"], main [class*="box--"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  /* Deal image gallery: the ACTIVE thumbnail carries a brand-orange border
     (`.carousel-thumbnail-item--active`) as the "you are here" indicator. The
     `* { border-color: #2d333b }` reset flattened it to the same grey as the
     inactive thumbs, so the selected image was no longer distinguishable.
     Restore the orange edge; (0,0,1,0) beats the `*` reset. */
  .carousel-thumbnail-item--active { border-color: #f7641b !important; }
  .userHtml, .userHtml *, .cept-description-container,
  [class*="description"] {
    color: #c4cdd6 !important;
  }
  .userHtml a { color: #5fb0e6 !important; }
  /* Comments / discussion */
  .comment, .cept-comment, [class*="comment--"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  /* Comment "like" / reply links ship a literal navy #186fbe — lift to a
     readable dark-mode blue. */
  .comment-like, .comment-reply, [class*="comment-like"],
  [class*="comment-action"] { color: #5fb0e6 !important; }

  /* ============================================================
     Sticky banners / overlays / modals must stay opaque
     ============================================================ */
  .modal, .modal-body, .dialog, [role="dialog"],
  [class*="modal"], [class*="overlay-content"],
  [class*="popover-content"], .cept-overlay-content {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  /* The "Lato Futbolu" promo strip + alert bars */
  .alert, [class*="alert--"], [class*="ribbon"] {
    color: inherit;
  }

  /* ============================================================
     Cookie / consent dialog (so it reads correctly before accept)
     ============================================================ */
  .consent, [class*="consent"], [id*="consent"],
  [class*="cookie"], [id*="cookie"] {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Coupons (/kupony) — a SEPARATE Next.js sub-app (unique #__next
     root; the home/search/detail Magritte pages have no #__next).
     It ships literal-white nav/sub-nav bars, white voucher cards and
     charcoal (#35373b) headings/body via hashed class names, so we
     scope a structural retheme to #__next and re-establish dark
     surfaces + light text there.
     ============================================================ */
  #__next, #__next .nalu, #__next main, #__next .main,
  #__next .track-containerWidth, #__next .section,
  #__next .category, #__next .section-placeholder {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }
  /* Top nav + the white sub-nav strip ("Top 20", "Wskazówki…") */
  #__next .nav, #__next nav, .subNav, .subNav--light,
  [data-t="subNav"], #__next [class*="subNav"] {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* The coupon tiles are literal-white hashed divs that no stable hook
     reaches individually. Since #__next is unique to this sub-app, blank
     every content background to transparent (so the dark #__next base
     shows through), then re-establish opaque elevated surfaces on the
     actual cards + opaque dark on any sticky/fixed bar (no bleed-through). */
  #__next main div, #__next main section,
  #__next main article, #__next main a, #__next main span,
  #__next main p, #__next main h1, #__next main h2,
  #__next main h3, #__next main h4, #__next main ul,
  #__next main li, #__next .track-containerWidth div,
  #__next header .nav-button,
  #__next header .button--mode-flat,
  #__next header button {
    background-color: transparent !important;
  }
  #__next header .nav-button span,
  #__next header .button--mode-flat span,
  #__next header button span { color: #c4cdd6 !important; }
  /* Voucher / coupon tiles -> elevated card. The grid items are the
     direct flex children that carry padding + their own (now-blanked) bg. */
  [id^="voucher-"], [id^="voucher-"] > div,
  #__next [class*="voucher"], #__next .category,
  #__next .track-containerWidth > div > div {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    border-radius: 8px !important;
  }
  /* "Najlepsze kody na dziś" coupon cards: each card body is a NATIVELY-WHITE
     wrapper (._13wrug0) and the card holds a banner photo (._1vopklm4, the top
     ~183px) with a caption strip ("Promocja / <merchant> / 20% rabatu") laid over
     the photo's lower edge. The #__next neutralizer blanked the white body, so the
     caption fell directly onto the bare (often bright) photo — orange-on-bright
     illegible. Restore a solid dark card body, then lay a bottom-up dark gradient
     scrim over the photo so the caption strip always has a readable dark backing
     while the photo subject still shows up top. */
  #__next [class*="_13wrug0"], #__next [class*="_13wrug2"],
  #__next [class*="_1vopklmt"] {
    background-color: #1c2128 !important;
  }
  #__next [class*="_1vopklm4"] { position: relative !important; }
  #__next [class*="_1vopklm4"]::after {
    content: "" !important;
    position: absolute !important;
    left: 0 !important; right: 0 !important; bottom: 0 !important;
    height: 55% !important;
    pointer-events: none !important;
    background: linear-gradient(to top, #14181d 0%, rgba(20, 24, 29, .85) 45%, rgba(20, 24, 29, 0) 100%) !important;
  }
  /* Belt-and-braces: a dark text-shadow keeps the caption + the "Tylko u nas"
     badge legible over the photo (incl. the badge up top, above the scrim)
     without a garish pill; invisible where labels already sit on the dark body. */
  #__next [class*="az57m4"],
  #__next [class*="_1qot0df1"] {
    text-shadow: 0 1px 2px rgba(0, 0, 0, .9), 0 0 4px rgba(0, 0, 0, .7) !important;
  }
  /* Keep any sticky/fixed coupon bar opaque dark so cards can't bleed
     through while scrolling */
  #__next [class*="sticky"], #__next [style*="position: sticky"],
  #__next [style*="position: fixed"] {
    background-color: #0d1117 !important;
  }
  /* Charcoal headings + body copy across the coupon app -> readable */
  #__next h1, #__next h2, #__next h3, #__next h4,
  #__next .title, #__next p, #__next li, #__next strong,
  #__next span, #__next a, #__next div, #__next dd, #__next dt {
    color: #c4cdd6 !important;
  }
  #__next h1, #__next h2, #__next h3, #__next h4,
  #__next .title { color: #e6edf3 !important; }
  #__next .subtitle, #__next .mute--text { color: #9aa6b0 !important; }
  /* Brand-orange coupon code/discount badges read as #ff7900 on the
     now-dark card — lift the tone so it harmonizes (matches feed). */
  #__next [class*="az57m4"], #__next [class*="_188gvwx"],
  #__next .text--color-brandPrimary { color: #ff8a4d !important; }
  /* "Ulubione marki i sklepy" brand chips (`_188gvwxj`): outlined pills with
     orange label + a soft brand-orange border (rgba(255,121,0,.5)) as the
     brand cue. The `* { border-color: #2d333b }` reset greyed the outline on
     all ~99 chips, leaving orange text in a flat grey pill. Restore the soft
     orange edge (muted to match the native 50%-alpha subtlety). */
  #__next a[class*="_188gvwxj"] { border-color: rgba(247, 100, 27, 0.5) !important; }
  /* A brand link's trailing chevron must match its label. The chevron is an
     icon-FONT glyph carrying an `l2mvoc` class, so the coupon icon rule
     `#__next [class*="l2mvoc"]` (1,0,1) — later in source — greyed it while the
     label above stayed orange: "Pokaż więcej ›" shipped as an orange label beside
     a grey arrow. Scope the accent to chevrons INSIDE a brand link (1,0,2) so the
     two read as one control; standalone l2mvoc chrome icons stay neutral. */
  #__next a[class*="_188gvwx"] [class*="l2mvoc"] { color: #ff8a4d !important; }
  /* "Czytaj więcej" SEO-text expand toggle (button.ekdzs0): its LABEL is a native
     brand-orange button-color, but the trailing arrow-drop is an icon-FONT glyph in
     the `l2mvoc` class, which our coupon icon rule `#__next [class*="l2mvoc"]` (1,0,1)
     — and `.nalu span` on the merchant shell — greyed to #c4cdd6, so an orange
     "Czytaj więcej" sat beside a grey arrow. Match the arrow to its label; the class
     is unique to this toggle. (1,0,2)/(0,0,3) beats those rules. */
  #__next button[class*="ekdzs"] [class*="l2mvoc"],
  .nalu button[class*="ekdzs"] [class*="l2mvoc"] { color: #ff8a4d !important; }
  /* The white search field inside the coupons hero */
  #__next input { background-color: #21262d !important; color: #e6edf3 !important; }

  /* Carousel prev/next arrow buttons on the coupon rails (`_1mt03451`, the
     "Najlepsze kody" + "Wasze ulubione sklepy" sliders): 51x51 buttons that
     keep a LITERAL white bg (the #__next neutralizer only blanks header
     buttons, not <main> ones). Their chevron is an icon-font glyph in the
     `l2mvoc` class, which our coupon rule lightens to #c4cdd6 — so a light
     chevron sat on a white circle = an invisible arrow AND a bright blob on
     the dark page. Darken the circle so the light chevron reads. */
  #__next button[class*="_1mt03451"] {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* ---- Merchant logo chip (coupon cards) ----
     Each voucher/merchant card shows a small square brand logo PNG
     (img.cwhjhh0, ~115x109) inside a wrapper (div.cwhjhh4 / .cwhjhh5). The
     #__next neutralizer blanks the formerly-white backing to transparent, so a
     dark logo (e.g. adidas, near-black) renders INVISIBLE on the dark card while
     light/colored logos still show. Give the logo + its immediate wrapper a
     LIGHT rounded tile so every merchant logo stays visible — a logo chip.
     NOT applied to the big top banner (._13wrug* / ._5u8p3p0). */
  #__next [class*="cwhjhh4"], #__next [class*="cwhjhh5"],
  #__next img[class*="cwhjhh0"] {
    background-color: #ffffff !important;
    border-radius: 8px !important;
  }
  #__next [class*="cwhjhh4"], #__next [class*="cwhjhh5"] {
    padding: 6px !important;
  }
  /* Small icon/tooltip chips (vanilla-extract l2mvoc*) keep a literal
     white bg — neutralize so their muted label isn't grey-on-white.
     Also catch the info-bar/tooltip bubble that wraps them. */
  #__next [class*="l2mvoc"],
  #__next [class*="i3rg26"],
  #__next [role="tooltip"], [role="tooltip"] {
    background-color: transparent !important;
  }
  #__next [class*="l2mvoc"], #__next [class*="i3rg26"],
  #__next [role="tooltip"] *, [role="tooltip"] * { color: #c4cdd6 !important; }
  [role="tooltip"] { background-color: #21262d !important; border-color: #2d333b !important; }

  /* Real CTA buttons inside the coupon app must keep their fill AND label. The
     broad `#__next main a/div/span { background: transparent }` neutralizer and
     the `#__next a/span/strong { color: #c4cdd6 }` text rule are ID-scoped
     (1,0,1), so they outrank the (0,0,1,0)/(0,0,2,0) button rules far above:
     the footer's PRIMARY "Dodaj do Chrome" brand CTA shipped as a transparent
     ghost with a grey label (indistinguishable from plain body text), and the
     "Obserwuj nas" social discs lost their grey fill. Re-establish each mode
     here — `#__next` + two classes = (1,0,2), which beats the neutralizer.
     Label stays dark on orange, matching every other brand pill in the theme. */
  #__next .button--type-primary.button--mode-brand {
    background-color: #f7641b !important;
    border-color: #f7641b !important;
  }
  #__next .button--type-primary.button--mode-brand,
  #__next .button--type-primary.button--mode-brand * {
    color: #1a1205 !important;
    -webkit-text-fill-color: #1a1205 !important;
  }
  #__next .button--type-primary.button--mode-brand svg,
  #__next .button--type-primary.button--mode-brand svg * {
    fill: #1a1205 !important;
  }
  #__next .button--type-primary.button--mode-grey {
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }
  #__next .button--type-primary.button--mode-grey,
  #__next .button--type-primary.button--mode-grey * { color: #e6edf3 !important; }
  #__next .button--type-primary.button--mode-grey svg,
  #__next .button--type-primary.button--mode-grey svg use { fill: #e6edf3 !important; }

  /* Footer stat highlights ("1 milion osób", "28 milionów komentarzy") are
     brand-orange <strong class="footer-highlight">. On /kupony the page footer
     sits INSIDE the #__next root, so `#__next strong` (1,0,1) beat the
     `footer [class*="highlight"]` (0,1,1) orange rule and the stats shipped flat
     grey — the emphasis the site paints on them was lost. (0,1,1)+id = (1,1,0)
     wins; the plain-footer arm keeps the home/deal pages correct. */
  #__next .footer-highlight,
  footer strong.footer-highlight { color: #ff8a4d !important; }

  /* ============================================================
     Merchant coupon pages (/kupony/<merchant>, e.g. /kupony/temu.com)
     ------------------------------------------------------------
     These render the coupon content WITHOUT the Next.js #__next root of
     the /kupony listing: the shell is server-rendered as <main>'s .nalu
     sections + a .p7sajb* sub-nav wrapper (both coupon-app-only markers —
     absent on home/deal). So every #__next-scoped coupon rule above misses
     this page and it shipped almost fully white with a black-text footer.
     Mirror the coupon retheme structurally here: dark base on the sections,
     blank the hashed white card/section fills to transparent, then
     re-establish elevated dark cards. Text is forced light (orange chips /
     "Szczegóły" links keep their own fill — buttons aren't recolored). */
  main > [class*="p7sajb"], main > .nalu.section, main > .nalu {
    background-color: #14181d !important;
  }
  .nalu section, .nalu > div, .nalu div,
  main > [class*="p7sajb"] div, main > [class*="p7sajb"] nav {
    background-color: transparent !important;
  }
  /* Re-establish elevated coupon cards / hero / info blocks + the white
     hero action button, over the dark base. */
  .nalu [class*="_13wrug"], .nalu [class*="_1jbscxu"],
  .nalu [class*="fed1vu"], .nalu [class*="_1w99urm"],
  .nalu [class*="_1tyhinu"], .nalu [class*="n9fwq6"],
  .nalu [class*="poqd91"], .nalu [class*="xvjmln"],
  .nalu button[class*="_62by6g"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Coupon-type filter chips ("Wszystkie / Kody / Promocje / Polecane"). The
     UNSELECTED chip is natively a white pill with an orange label AND an orange
     OUTLINE — the outline is what marks the row as a set of brand filter chips.
     Our own rule below used to grey that border to #2d333b (and the `* {
     border-color }` reset greys the selected chip's too), so an orange label sat
     in a flat grey pill and the row read as inert chrome. Keep the dark fill,
     put the orange edge back on every chip; the selected one keeps its orange
     fill + white label (a different hashed variant). */
  .nalu button[class*="_175sa5n"] { border-color: #f7641b !important; }
  .nalu button[class*="_175sa5n2"] {
    background-color: #21262d !important;
    border-color: #f7641b !important;
  }
  /* Coupon author byline (`az57m4r` inside a `_188gvwx` link, e.g. "Agnieszka
     Zygmunt"): natively a brand-orange LINK. The broad `.nalu a/span { color:
     #c4cdd6 }` text rule greyed it, so it read as plain body text and lost its
     clickable affordance. The breadcrumb `_188gvwx2` links beside it are natively
     neutral, so scope to the byline span rather than the whole link class. */
  .nalu [class*="az57m4r"] { color: #ff8a4d !important; }
  /* "Pokaż kod" reveal-code CTA (`_1fgcb8y*`): the PRIMARY action on every coupon
     card — natively a solid brand-orange pill with white label + arrow. The broad
     `.nalu div { background: transparent }` neutralizer above blanked its fill, so it
     shipped as a grey ghost button indistinguishable from a secondary link. Restore
     the orange fill with the native white label + arrow, on both the `.nalu` merchant
     shell and the `#__next` /kupony listing. The label paints via `-webkit-text-fill-color`,
     so `color` alone leaves it grey while the SVG arrow flips — force both to white. */
  .nalu [class*="_1fgcb8y"], #__next [class*="_1fgcb8y"] {
    background-color: #f7641b !important;
    border-color: #f7641b !important;
  }
  .nalu [class*="_1fgcb8y"], .nalu [class*="_1fgcb8y"] *,
  #__next [class*="_1fgcb8y"], #__next [class*="_1fgcb8y"] * {
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .nalu [class*="_1fgcb8y"] svg, .nalu [class*="_1fgcb8y"] svg *,
  #__next [class*="_1fgcb8y"] svg, #__next [class*="_1fgcb8y"] svg * { fill: #fff !important; }
  /* Force the coupon-app body text light — its utility classes resolve to
     literal charcoal/black (they don't read our tokens), so headings, card
     titles, the "N% ZNIŻKI" discount and the details table all shipped
     dark-on-dark. */
  .nalu, .nalu p, .nalu span, .nalu div, .nalu li, .nalu strong,
  .nalu h1, .nalu h2, .nalu h3, .nalu h4, .nalu h5, .nalu h6, .nalu a,
  .nalu td, .nalu th, .nalu table,
  main > [class*="p7sajb"] a, main > [class*="p7sajb"] span,
  main > [class*="p7sajb"] div {
    color: #c4cdd6 !important;
  }
  .nalu h1, .nalu h2, .nalu h3, .nalu h4 { color: #e6edf3 !important; }
  .nalu a:hover { color: #ffffff !important; }
  /* Restore the coupon app's brand-orange accents on the merchant `.nalu`
     shell. Unlike the `#__next` /kupony listing, this server-rendered shell
     has no #__next root, so the orange-restoring rules above miss it and the
     broad `.nalu div/span/a { color: #c4cdd6 }` text rule greyed native orange
     (#ff7900) accents: the "Kod" coupon-type tag (`_1l9o1jz`), the
     offer-verified check icon (`_1bnyxcg`) and the "Ulubione marki" brand-chip
     labels (`_188gvwx`). Put the orange back so these read as brand accents.
     (The big "N% ZNIŻKI" discount and the rating stars are NOT restored: both
     are natively dark-on-white — dark text / black stars — so our light-grey
     adaptation is correct, not a flattened orange.) */
  .nalu [class*="_1l9o1jz"], .nalu [class*="_1bnyxcg"],
  .nalu a[class*="_188gvwxj"] {
    color: #ff8a4d !important;
  }
  .nalu a[class*="_188gvwxj"] { border-color: rgba(247, 100, 27, 0.5) !important; }
  /* The "offer-verified" seal beside the "Kod"/"Promocja" tag is a single-colour
     icon-font glyph (a `l2mvoc` child of the `_1bnyxcg` wrapper) painted brand
     orange natively. The wrapper rule above lights the wrapper, but the coupon
     icon rule `#__next [class*="l2mvoc"]` / `.nalu span` greyed the actual glyph,
     so the seal shipped neutral grey instead of orange. Match the glyph to the
     wrapper on both the merchant shell and the /kupony listing. */
  .nalu [class*="_1bnyxcg"] [class*="l2mvoc"],
  #__next [class*="_1bnyxcg"] [class*="l2mvoc"] {
    color: #ff8a4d !important;
    fill: #ff8a4d !important;
  }
  /* "CASHBACK" offer-type badge (`e1pdso0` variant of the `_1l9o1jz` tag): unlike
     the "Kod"/"Promocja" tags — an outlined icon + orange TEXT — cashback offers
     ship a SOLID orange PILL with a dark label + icon, a more prominent highlight.
     The `.nalu div { background: transparent }` neutralizer blanked the fill and
     the `_1l9o1jz` colour rule painted the label orange, so it collapsed to plain
     orange text and lost the filled-badge distinction. Restore the orange pill +
     dark label/icon on both the merchant shell and the /kupony listing. */
  .nalu [class*="e1pdso0"], #__next [class*="e1pdso0"] {
    background-color: #ff8a4d !important;
    border-radius: 10px !important;
  }
  .nalu [class*="e1pdso0"], .nalu [class*="e1pdso0"] *,
  #__next [class*="e1pdso0"], #__next [class*="e1pdso0"] * {
    color: #1a1205 !important;
  }
  .nalu [class*="e1pdso0"] svg, .nalu [class*="e1pdso0"] svg *,
  #__next [class*="e1pdso0"] svg, #__next [class*="e1pdso0"] svg * { fill: #1a1205 !important; }

  /* Header nav pills on the merchant coupon shell (Kategorie / Kupony /
     Za darmo / Okazje / Dyskusje / Club): these pages render the header with a
     #header-navigation sub-nav whose .button--mode-flat pills (a mix of
     <button> dropdowns and <a> links) fall back to a LITERAL white bg — the
     Magritte token frontend that resolves them to #1c2128 on home/deal isn't
     loaded here, and there's no #__next root, so every coupon-app rule above
     misses them. They're short (~40px) pills in a sticky header that scrolls
     off = audit-blind. #header-navigation is ABSENT on the home/deal header
     (its pills already compute #1c2128 from tokens), so scoping here darkens
     ONLY the coupon shell — no home/deal regression. Match the home pill shade;
     orange CTAs keep their own fill (later brand-CTA rules, !important). */
  #header-navigation .button--mode-flat {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  #header-navigation .button--mode-flat:hover {
    background-color: #2d333b !important;
  }

  /* Horizontal-scroll fade on coupon tag rows: the tag strip (_9yil9*, on
     both the /kupony listing and the /kupony/<merchant> shells) paints a
     ::before scroll-fade gradient that fades to LITERAL white
     (rgba(255,255,255,0) -> #fff) to hint "more tags to the right". It's
     pointer-events:none = invisible to element-bg AND hit-test audits, and
     on our dark card it read as a bright white block at the row's right
     edge. Recolor the fade to the card shade so the affordance survives
     without the white bleed. */
  [class*="_9yil9"]::before, [class*="_9yil9"]::after {
    background-image: linear-gradient(to right, rgba(28, 33, 40, 0), #1c2128) !important;
  }

  /* Hidden coupon-code preview strip (merchant coupon cards): its right-edge
     "more code to the right" scroll-fade is drawn by a WHITE inset box-shadow
     on _635p650::before (box-shadow, NOT a background/gradient — so element-bg
     AND gradient audits both miss it, and it's on a pseudo). On our dark card it
     read as a bright white smear at the strip's right end. Recolor the inset
     shadow to a dark elevated shade so the fade affordance survives as a soft
     edge sheen without the white bleed. */
  [class*="_635p65"]::before {
    box-shadow: #2d333b -9px 0 6px -3px inset !important;
  }

  /* ============================================================
     Generic links + footer
     ============================================================ */
  a { color: #c4cdd6; }
  a:hover { color: #ffffff !important; }
  .link, a.link, [class*="link--"] { color: #5fb0e6 !important; }

  /* The selected feed / search tab ("Popularne", "Wszystkie", "Okazje") is
     brand orange natively. Two later blanket rules stole it back: the anchor
     matched `[class*="link--"]` (painted link-blue) and its label <span>
     matched `main [class*="box--"]` at (0,0,1,1) (painted neutral). Only the
     orange ::after underline survived, so the ACTIVE tab read the same as its
     neighbours. `a.<class> span` is (0,0,1,2) — it beats both. */
  a.subNavMenu-link--selected, a.subNavMenu-link--selected span,
  a.navMenu-link--selected, a.navMenu-link--selected span {
    color: #ff8a4d !important;
    background-color: transparent !important;
  }

  /* Page footer ONLY — the real <footer class="footer …"> at the very bottom.
     Scoped tightly to the footer ELEMENT (footer / footer.footer): a bare
     [class*="footer"] was far too broad and also matched each deal card's
     bottom action row (.threadListCard-footer) + keyword-suggestion dropdowns,
     painting them this near-black #0d1117 — a darker BAND across every card. */
  footer, footer.footer {
    background-color: #0d1117 !important;
    color: #9aa6b0 !important;
    border-top: 1px solid #2d333b !important;
  }
  footer a { color: #9aa6b0 !important; }
  footer a:hover { color: #e6edf3 !important; }
  /* The expanded footer on /kupony/<merchant> pages colours its headings /
     trust-signals / ratings / copyright with literal light-mode charcoal &
     black via utility classes (not tokens), so they shipped dark-on-dark on
     our #0d1117 footer. Force footer descendant text light; keep column
     headings brighter and preserve the brand-orange stat highlights. */
  footer div, footer p, footer span, footer strong, footer li,
  footer [class*="text--"], footer [class*="color--text"],
  footer [class*="footer-"] {
    color: #9aa6b0 !important;
  }
  footer h1, footer h2, footer h3, footer h4,
  footer [class*="footer-"] [class*="text--b"] { color: #e6edf3 !important; }
  footer [class*="highlight"] { color: #ff8a4d !important; }
  /* App-store rating stars in the footer (.footer-apps "4,6 ★★★★★"): the SVG
     star glyphs carry `text--color-yellow`, so the footer text rule
     `footer [class*="text--"]` (equal specificity, later in source) greyed
     them out — a gold rating read as neutral grey. Restore the gold; scoped
     to star icons only so the "4 800+ Ocen" caption stays muted. */
  footer svg[class*="icon--star"], footer svg[class*="icon--star"] use {
    color: #f3a21c !important;
    fill: #f3a21c !important;
  }
  /* The deal-card action row (comment / share / bookmark + "Idź do okazji")
     carries a "footer" classname too — keep it TRANSPARENT so it inherits the
     #1c2128 card body and the card reads as one uniform surface (no band). */
  [class*="threadListCard-footer"], [class*="threadGrid-footer"],
  .thread-footer, .cept-thread-footer,
  article [class*="-footer"], [class*="thread"] [class*="-footer"] {
    background-color: transparent !important;
    border-top: none !important;
  }

  /* ============================================================
     Popover / flyout menus (Menu, Kategorie) — white panels with
     black text on the legacy layout; make opaque dark + light text.
     ============================================================ */
  /* Only `.popover-content` paints natively. Its ancestors are structural:
     `.popover--layout-fixed` is a `position:fixed; inset:0; pointer-events:none`
     flex centering box and `.popover-cover` is the dimming scrim
     (`--bgTranslucentOverlay`, #010408ad). Painting those two solid #1c2128 —
     which a bare `[class*="popover"]` did — replaced the whole viewport with a
     raised grey slab the moment the Kategorie / Menu flyout opened, hiding the
     feed instead of dimming it. Keep the wrappers transparent, the scrim
     translucent, and put the surface back on the panel itself. */
  .popover, [class*="popover--"], .popover-portal, .popover-origin {
    background-color: transparent !important;
  }
  .popover-cover { background-color: rgba(1, 4, 8, 0.68) !important; }
  .popover-content, [class*="popover-content"],
  .flyout, [class*="flyout"],
  .popover-content [class*="category"],
  [class*="popover-content"] [class*="category"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }
  /* Every descendant of a flyout/popover -> light text + transparent
     so no inner light panel leaks through the category mega-menu. */
  .popover-content *, [class*="popover-content"] *,
  [class*="flyout"] * {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .popover-content [class*="title"], [class*="popover-content"] [class*="title"],
  .popover-content h1, .popover-content h2, .popover-content h3 {
    color: #e6edf3 !important;
  }
  .popover-content a:hover, [class*="popover-content"] a:hover {
    color: #ffffff !important;
  }
  /* "Zobacz wszystkie" / link-styled items inside flyouts */
  .popover-content .link, [class*="popover-content"] .link,
  .popover-content [class*="link"], [class*="popover-content"] [class*="link"] {
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Polish — selection, focus, card hover, accent harmony
     ============================================================ */
  /* Text selection in a refined Pepper orange */
  ::selection { background-color: #f7641b !important; color: #1a1205 !important; }
  ::-moz-selection { background-color: #f7641b; color: #1a1205; }

  /* Keyboard focus ring — visible warm-orange outline for accessibility */
  a:focus-visible, button:focus-visible, input:focus-visible,
  textarea:focus-visible, select:focus-visible,
  [tabindex]:focus-visible, [role="button"]:focus-visible {
    outline: 2px solid #ff8a4d !important;
    outline-offset: 2px !important;
  }
  /* Input focus — orange border + subtle glow, no harsh blue UA ring */
  .input:focus, input:focus, textarea:focus, select:focus {
    border-color: #f7641b !important;
    box-shadow: 0 0 0 2px #f7641b40 !important;
    outline: none !important;
  }
  /* Subtle lift on deal-card hover so the grid feels responsive */
  .thread:hover, .cept-thread-item:hover, [class*="thread--deal"]:hover {
    border-color: #3a424c !important;
    background-color: #20262e !important;
  }
  /* Reusable hover for secondary/ghost buttons + chips already set;
     give plain icon buttons a readable hover bg too */
  .vote-button:hover, .cept-vote-button:hover { color: #ff8a4d !important; }

  /* ============================================================
     Scrollbar polish
     ============================================================ */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #0d1117; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a424c; }
}
